/// <summary>
/// Constructs the reference identities used to populate the <c>METOrderExtractScreen</c> form.
/// </summary>
public class METOrderExtractScreenProcessor
{
    MetOrderExtractScreenTmp                metOrderExtractScreenTmp;
    MEtOrderExtractScreenParameters         metOrderExtractScreenParameters;
    SalesTable                              salesTable;
    SalesLine                               salesLine;
    METSalesLine                            metSalesLine;
    MetItemSiteSettingsSetup                itemSiteSettings;
    InventDim                               inventDim;
    ReqItemTable                            reqItemTable;
    METReqItemTable                         metReqItemTable;        
    InventDim                               inventDimReq;
    METInventLocation                       metInventLocation;

    InventQty                               cases;
    InventSiteId                            site;
    InventLocationId                        warehouse;
    METRoute                                route;
    SalesShippingDateConfirmed              shippingDateFrom;
    SalesShippingDateConfirmed              shippingDateTo;
    METFilterCodeone                        category;
    Volume                                  totalVolume;
    METOrderExtractStatus                   extracted;
    METTotalPallets                         totalPallets;
    //CS - CB173_SalesOrderExtract - PS
    METOrderSplitGroup                      osg;
    METSalesOrderTypeID                     salesOrderType;
    CustAccount                             custAcc;
    METSalesTable                           metSalestbl;
    //CE - CB173_SalesOrderExtract - PS
    Map                                     volumeMap;
    Map                                     itemTypeMap;
    MapEnumerator                           mapEnum;

}

