/// <summary>
/// Sets total pallets
/// </summary>
/// <param name = "_pallets">Total palletslume</param>
/// <returns>Pallets</returns>
public METTotalPallets parmTotalpallets(METTotalPallets _pallets = totalPallets)
{
    totalPallets = _pallets;
    return totalPallets;
}

/// <summary>
/// set or get <c>MEtOrderExtractScreenParameters</c> class instance.
/// </summary>
/// <param name = "_metOrderExtractScreenParameters"><c>MEtOrderExtractScreenParameters</c> class instance.</param>
/// <returns><c>MEtOrderExtractScreenParameters</c> class instance</returns>
public MEtOrderExtractScreenParameters parmMETOrderExtractScreenParams(
    MEtOrderExtractScreenParameters _metOrderExtractScreenParameters)
{
    MEtOrderExtractScreenParameters = _metOrderExtractScreenParameters;
    return MEtOrderExtractScreenParameters;
}

    /// <summary>
    /// set or get <c>METOrderExtractScreenTmp</c> table instance.
    /// </summary>
    /// <param name = "_metOrderExtractScreenTmp"><c>METOrderExtractScreenTmp</c> table instance</param>
    /// <returns><c>METOrderExtractScreenTmp</c> table instance</returns>
    public METOrderExtractScreenTmp parmMETOrderExtractScreenTmp(
        METOrderExtractScreenTmp _metOrderExtractScreenTmp = metOrderExtractScreenTmp)
    {
        metOrderExtractScreenTmp.linkPhysicalTableInstance(_metOrderExtractScreenTmp);

        return metOrderExtractScreenTmp;
    }

/// <summary> /// Extracts all the orders by salesid and category based on the filters. /// </summary> public void insertOrders() { //Case1: Insert records group by SalesId & Category insert_recordset metOrderExtractScreenTmp(SalesId, LineNum, FilterCodeOne) select SalesId, minof(LineNum) from salesLine group by salesLine.SalesId, itemSiteSettings.FilterCode1 where salesLine.SalesStatus == SalesStatus::Backorder && salesLine.SalesQty > 0 join salesTable where salesTable.SalesId == salesLine.SalesId && (salesTable.DocumentStatus != DocumentStatus::None && salesTable.DocumentStatus != DocumentStatus::Cancelled) && salesTable.SalesType == SalesType::Sales && salesTable.METOrderExtractStatus == extracted && (!route || salesTable.METRoute == route) && (salesTable.ShippingDateConfirmed >= shippingDateFrom && salesTable.ShippingDateConfirmed <= shippingDateTo) && (!salesTable.InterCompanyOriginalSalesId) //TODO: Added here for testing && (!custAcc || salesTable.CustAccount == custAcc) && (!salesOrderType || salesTable.METSalesOrderType == salesOrderType) /*join metSalestbl where metSalestbl.SalesId == salesTable.SalesId && (!osg || metSalestbl.OrderSplitGroup)*/ //TODO ends join inventDim where inventDim.inventDimId == salesLine.InventDimId && (!site || inventDim.InventSiteId == site) && (!warehouse || inventDim.InventLocationId == warehouse) join FilterCode1 from itemSiteSettings where itemSiteSettings.ItemId == salesLine.ItemId && itemSiteSettings.InventSiteId == inventDim.InventSiteId && (!category || itemSiteSettings.FilterCode1 == category);
//Update order split category code update_recordset metOrderExtractScreenTmp setting OSCCode = metReqItemTable.OSCCode join RecId from salesLine where salesLine.SalesId == metOrderExtractScreenTmp.SalesId && salesLine.LineNum == metOrderExtractScreenTmp.LineNum && salesLine.SalesStatus == SalesStatus::Backorder && salesLine.SalesQty > 0 join RecId from inventDim where inventDim.inventDimId == salesLine.InventDimId && (!site || inventDim.InventSiteId == site) && (!warehouse || inventDim.InventLocationId == warehouse) join ItemType from itemSiteSettings where itemSiteSettings.ItemId == salesLine.ItemId && itemSiteSettings.InventSiteId == inventDim.InventSiteId && itemSiteSettings.FilterCode1 == metOrderExtractScreenTmp.FilterCodeOne join Recid from reqItemTable where reqItemTable.ItemId == salesLine.ItemId join OSCCode from metReqItemTable where metReqItemTable.RefRecId == reqItemTable.RecId exists join inventDimReq where inventDimReq.InventSiteId == inventDim.InventSiteId && InventDimReq.InventLocationId == inventDim.InventLocationId && inventDimReq.inventDimId == reqItemTable.CovInventDimId;
}

    /// <summary>
    /// Calculates the sum of Weight, Volume, Case and Broken case values of the orders extracted.
    /// </summary>
    /// <param name = "_metOrderExtractScreenTmp"><c>METOrderExtractScreenTmp</c> table instance</param>
    public void calculate(METOrderExtractScreenTmp  _metOrderExtractScreenTmp)
    {
        #define.Million(1000000000)
        #OCCRetryCount
        try
        {
            this.initParams();
            totalPallets = this.parmTotalpallets();
            metOrderExtractScreenTmp.linkPhysicalTableInstance(_metOrderExtractScreenTmp);

            //Clear computed values before calculating.
            update_recordset metOrderExtractScreenTmp
                setting weight = 0, Volume = 0, Cases = 0, BrokenCase = 0, ActualCases = 0, ActualBrokenCases = 0, ActualVolume = 0, ActualWeight = 0;

            
            METItemTypes        itemTypes;
            volumeMap           = new Map (Types::String, Types::Real);
            itemTypeMap         = new Map (Types::String, Types::String);  
        
            while select metOrderExtractScreenTmp
                join  ItemId, SalesQty, SalesUnit, InventDimId from salesLine
                    where  salesLine.SalesStatus == SalesStatus::Backorder
                    && salesLine.SalesQty > 0
                    && salesLine.SalesId == metOrderExtractScreenTmp.SalesId
                join SalesUnitVolume, SalesUnitWeight from metSalesLine
                    where metSalesLine.SalesLine == salesLine.RecId
                join InventSiteId, InventLocationId from inventDim
                    where inventDim.inventDimId == salesLine.InventDimId
                    && (!site || inventDim.InventSiteId == site)
                    && (!warehouse || inventDim.InventLocationId == warehouse)
                join ItemType from itemSiteSettings
                    where itemSiteSettings.ItemId == salesLine.ItemId
                    &&  itemSiteSettings.InventSiteId == inventDim.InventSiteId
                    &&  itemSiteSettings.FilterCode1 == metOrderExtractScreenTmp.FilterCodeOne
            {              
                //If there are multiple items in the order with different item type then show Multiple*
                if (itemTypeMap.exists(metOrderExtractScreenTmp.SalesId)
                    && itemTypeMap.lookup(metOrderExtractScreenTmp.SalesId) != itemSiteSettings.ItemType)
                {
                    itemTypeMap.insert(metOrderExtractScreenTmp.SalesId, METConstants::ItemTypeMultiple);
                    itemTypes = METConstants::ItemTypeMultiple;
                }
                else
                {
                    itemTypeMap.insert(metOrderExtractScreenTmp.SalesId, itemSiteSettings.ItemType);
                    itemTypes = itemSiteSettings.ItemType;
                }
                Info(strFmt(any2Str(salesline.SalesId)));
                Info(strFmt(any2Str(salesline.RecId)));
                Info(strFmt(any2Str(salesLine.displayMETcases())));

                salesLine   sl = SalesLine::findRecId(salesline.RecId);
                //Info(strFmt(any2Str(salesLine.displayMETActualcases())));
                //TODO: Write logic in select query and below code for case, volume, weight
                ttsbegin;
                metOrderExtractScreenTmp.reread();
                metOrderExtractScreenTmp.selectForUpdate(true);
                metOrderExtractScreenTmp.Weight     += salesLine.SalesQty * metSalesLine.SalesUnitWeight;
                metOrderExtractScreenTmp.Volume     += salesLine.SalesQty * metSalesLine.SalesUnitVolume;
                metOrderExtractScreenTmp.ItemType   =   itemTypes;
                metOrderExtractScreenTmp.Cases      +=  salesLine.displayMETcases();
                metOrderExtractScreenTmp.BrokenCase +=  salesLine.displayMETBrokenCase();
                metOrderExtractScreenTmp.ActualBrokenCases += sl.displayMETActualBrokenCase();//salesLine.displayMETActualBrokenCase();
                metOrderExtractScreenTmp.ActualCases += sl.displayMETActualCases();//salesLine.displayMETActualCases();
                metOrderExtractScreenTmp.ActualVolume += sl.displayMETActualUnitVolume()/#Million;//salesLine.displayMETActualUnitVolume();//salesLine.SalesQty * metSalesLine.ActualUnitVolume; //TODO: reserve qty
                metOrderExtractScreenTmp.ActualWeight += sl.displayMETActualWeight();//salesLine.displayMETActualWeight();//salesLine.SalesQty * metSalesLine.ActualUnitWeight; //TODO: reserve qty
                metOrderExtractScreenTmp.update();
                ttscommit;

                //Calculate volume by warehouse. This will be required to calculate total pallets.
                if (volumeMap.exists(inventDim.InventLocationId))
                {
                    volumeMap.insert(inventDim.InventLocationId, metOrderExtractScreenTmp.Volume +  volumeMap.lookup(inventDim.InventLocationId));
                }
                else
                {
                    volumeMap.insert(inventDim.InventLocationId, metOrderExtractScreenTmp.Volume);
                }
            }
            
            //Calculate total pallets
            if (volumeMap && volumeMap.elements())
            {
                totalPallets = 0;
                mapEnum = volumeMap.getEnumerator();

                while (mapEnum.moveNext())
                {
                    //Calculate pallets
                    metInventLocation = METInventLocation::findByInventLocationId(mapEnum.currentKey());
                    if (metInventLocation.WHSPalletVolume)
                    {
                        totalPallets += roundUp((mapEnum.currentValue()/metInventLocation.WHSPalletVolume), 1);
                    }
                }
            }
            this.parmTotalpallets(totalPallets);
        }
        catch (Exception::Error)
        {
            error("@MET:METBulkUpdateError");
        }

        catch (Exception::UpdateConflict)
        {
            if (appl.ttsLevel() == 0)
            {
                if (xSession::currentRetryCount() >= #RetryNum)
                {
                    throw Exception::UpdateConflictNotRecovered;
                }
                else
                {
                    retry;
                }
            }
            else
            {
                throw Exception::UpdateConflict;
            }
        }

    }

    /// <summary>
    /// Constructs the order extract screen.
    /// </summary>
    /// <param name="_metOrderExtractScreenTmp">
    /// The <c>METOrderExtractScreenTmp</c> instance.
    /// </param>
    /// <param name="_metOrderExtractScreenParameters">
    /// An instance of <c>METOrderExtractScreenParameters</c> to filter the order extract screen form.
    /// </param>
    /// <returns>METOrderExtractScreenProcessor class instance.</returns>
    public static METOrderExtractScreenProcessor construct(
        METOrderExtractScreenTmp                _metOrderExtractScreenTmp,
        METOrderExtractScreenParameters         _metOrderExtractScreenParameters)
    {
        METOrderExtractScreenProcessor   metOrderExtractScreenProcessor;

        metOrderExtractScreenProcessor = new METOrderExtractScreenProcessor();

        metOrderExtractScreenProcessor.populateOrderExtractScreen(_metOrderExtractScreenTmp, _metOrderExtractScreenParameters);

        return metOrderExtractScreenProcessor;
    }

/// <summary>
/// Initialise parameters.
/// </summary>
protected void initParams()
{
    site                = metOrderExtractScreenParameters.parmSite();
    warehouse           = metOrderExtractScreenParameters.parmWarehouse();
    route               = metOrderExtractScreenParameters.parmRoute();
    shippingDatefrom    = metOrderExtractScreenParameters.parmShippingDateConfirmFrom();
    shippingDateTo      = metOrderExtractScreenParameters.parmShippingDateConfirmTo();
    category            = metOrderExtractScreenParameters.parmCategory();
    extracted           = metOrderExtractScreenParameters.parmExtracted();
    //CS - CB173_SalesOrderExtract - PS
    osg                 = metOrderExtractScreenParameters.parmOrderSplitGroup();
    salesOrderType      = metOrderExtractScreenParameters.parmOrderType();
    custAcc             = metOrderExtractScreenParameters.parmCustAccount();
    //CE - CB173_SalesOrderExtract - PS
}

    /// <summary>
    /// Populates <c>METOrderExtractScreenTmp</c> table for the grid on the order extract screen form.
    /// </summary>
    /// <param name="_metOrderExtractScreenTmp">
    /// The <c>METOrderExtractScreenTmp</c> instance.
    /// </param>
    /// <param name="_metOrderExtractScreenParameters">
    /// An instance of <c>METOrderExtractScreenParameters</c> to filter the order extract screen form.
    /// </param>
    public void populateOrderExtractScreen(METOrderExtractScreenTmp                _metOrderExtractScreenTmp,
                                            METOrderExtractScreenParameters         _metOrderExtractScreenParameters)
    {
        METOrderExtractScreenProcessor           metOrderExtractScreenProcessor;

        metOrderExtractScreenProcessor = new METOrderExtractScreenProcessor();

        metOrderExtractScreenProcessor.parmMETOrderExtractScreenParams(_metOrderExtractScreenParameters);
        metOrderExtractScreenProcessor.parmMETOrderExtractScreenTmp(_metOrderExtractScreenTmp);
        metOrderExtractScreenProcessor.initParams();
        metOrderExtractScreenProcessor.insertOrders();
        this.parmTotalpallets(metOrderExtractScreenProcessor.parmTotalpallets());
    }
